class Solution {
public:
    int equalCountSubstrings(string s, int count) {
        int n = s.size(), answer = 0;
        for (int distinct = 1; distinct <= 26 && distinct * count <= n; ++distinct) {
            int width = distinct * count;
            int freq[26] = {};
            int good = 0;
            auto adjust = [&](int c, int delta) {
                if (freq[c] == count) --good;
                freq[c] += delta;
                if (freq[c] == count) ++good;
            };
            for (int i = 0; i < n; ++i) {
                adjust(s[i] - 'a', 1);
                if (i >= width) adjust(s[i - width] - 'a', -1);
                if (i >= width - 1 && good == distinct) ++answer;
            }
        }
        return answer;
    }
};
